async function initDatabase(){return new Promise((resolve,reject)=>{const req=indexedDB.open('viva-studio',1);req.onupgradeneeded=()=>req.result.createObjectStore('projects');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});}
