async function restoreRaw(raw){validateProject(raw);setTaskProgress('Preparando los audios del proyecto…');await new Promise(resolve=>setTimeout(resolve,15));const ctx=await engine.init(false);const staged=new Map();for(const [key,source] of Object.entries(raw.sources)){if(!Number.isFinite(source.rate)||source.rate<8000||source.rate>192000||!Array.isArray(source.channels)||source.channels.length<1||source.channels.length>2)throw Error('El proyecto contiene un audio inválido.');const arrays=source.channels.map(a=>new Float32Array(typeof a==='string'?fromBase64(a):a));if(!arrays[0].length||arrays.some(a=>a.length!==arrays[0].length))throw Error('El audio del proyecto está incompleto.');for(const array of arrays)for(let i=0;i<array.length;i++)if(!Number.isFinite(array[i]))throw Error('Muestras de audio inválidas.');const buffer=ctx.createBuffer(arrays.length,arrays[0].length,source.rate);arrays.forEach((a,i)=>buffer.copyToChannel(a,i));staged.set(key,buffer);}for(const t of raw.project.tracks)for(const c of t.clips){if(c.offset+c.duration>staged.get(c.source).duration+.001)throw Error('Un clip excede la duración de su audio.');}stopPlayback();sources.clear();for(const [k,v] of staged)sources.set(k,v);project=cloneProject(raw.project);for(const t of project.tracks)for(const c of t.clips)c.volumePoints=volumeNodes(c);selectedTrack=project.tracks[0]?.id;selectedClip=null;clipboard=null;previewPlan=null;welcomeDismissed=true;history=[];future=[];position=0;loop=false;render();fitZoom();finishTaskProgress('Proyecto cargado con todos sus audios');}
function fromBase64(s){const str=atob(s),array=new Uint8Array(str.length);for(let i=0;i<str.length;i++)array[i]=str.charCodeAt(i);if(array.length%4)throw Error('Archivo de audio dañado.');return array.buffer;}
