async function startPlayback(){if(recordPending||exporting||importing)return;if(!recording&&projectDuration(project)===0){notify('Importa un audio o graba con el micrófono para empezar.');return;}const token=++playToken;try{let end=recording?86400:previewPlan?.end??(loop&&project.region?project.region.end:projectDuration(project));if(position>=end)position=previewPlan?.start??(loop&&project.region?project.region.start:0);await engine.init();if(token!==playToken)return;const started=await engine.play(previewPlan?.project||project,position,end);if(token!==playToken||!started)return;$('#playBtn').innerHTML=icon('pause');status(recording?'Grabando micrófono…':'Reproduciendo la mezcla');}catch(e){notify(e.message,true);}}
function stopPlayback(reset=false){++playToken;if(engine.running)position=engine.time;engine.stop();if(reset)position=0;$('#playBtn').innerHTML=icon('play');updatePlayhead();}
function refreshAudio(){if(engine.running&&!recording){if(previewPlan){try{previewPlan=exportPlan(previewPlan.scope);}catch{previewPlan=null;}}position=engine.time;stopPlayback();startPlayback();}}
function seek(t){if(recording||recordPending||importing||exporting)return;previewPlan=null;const playing=engine.running;stopPlayback();position=Math.max(0,t);updatePlayhead();if(playing)startPlayback();}
async function togglePlay(){if(recording){await stopRecording();return;}if(engine.running)stopPlayback();else await startPlayback();}
function animate(){frame=requestAnimationFrame(animate);if(recording&&!recorder?.stopping&&!engine.running){position=recording.start+(performance.now()-recorder.startedWall)/1000;updatePlayhead();}if(engine.running){position=engine.time;updatePlayhead();const end=previewPlan?.end??(loop&&project.region?project.region.end:projectDuration(project));if(!recording&&position>=end){if(loop&&end>0){stopPlayback();position=project.region?.start??0;startPlayback();}else{stopPlayback();previewPlan=null;position=end;updatePlayhead();status('Reproducción finalizada');}}if(recording){const expected=trackWidth()+timelineDuration()*zoom;if(parseFloat($('#timeline').style.width)<expected-zoom*4){$('#timeline').style.width=expected+'px';}const sc=$('#arrangeScroll'),x=trackWidth()+position*zoom;if(x-sc.scrollLeft>sc.clientWidth-50)sc.scrollLeft=x-sc.clientWidth+100;}}
for(const el of $$('[data-meter]')){const node=el.dataset.meter==='master'?engine.masterAnalyser:engine.chains.get(el.dataset.meter)?.analyser;const value=engine.running?engine.meter(node):0;for(const bar of el.children)bar.style.height=(value*100)+'%';}updateMicrophoneMeter();}
let taskProgressTimer;
function setTaskProgress(label,value=null){clearTimeout(taskProgressTimer);const box=$('#taskProgress'),bar=$('#taskProgressBar');box.hidden=false;box.classList.remove('task-error');$('#taskProgressLabel').textContent=label;if(value===null){bar.removeAttribute('value');$('#taskProgressValue').textContent='Procesando…';}else{bar.value=clamp(value,0,100);$('#taskProgressValue').textContent=Math.round(bar.value)+' %';}}
function finishTaskProgress(label,error=false){setTaskProgress(label,error?null:100);$('#taskProgress').classList.toggle('task-error',error);if(error)$('#taskProgressValue').textContent='Revisa el archivo';taskProgressTimer=setTimeout(()=>$('#taskProgress').hidden=true,error?4500:1800);}
function hideTaskProgress(){clearTimeout(taskProgressTimer);$('#taskProgress').hidden=true;}
async function readAudioFile(file,label){if(typeof FileReader==='undefined'||!(file instanceof Blob)){setTaskProgress(label);return file.arrayBuffer();}return new Promise((resolve,reject)=>{const reader=new FileReader();reader.onprogress=e=>setTaskProgress(label,e.lengthComputable?e.loaded/e.total*100:null);reader.onload=()=>resolve(reader.result);reader.onerror=()=>reject(reader.error||Error('No se pudo leer el archivo.'));reader.onabort=()=>reject(Error('Carga cancelada.'));setTaskProgress(label,0);reader.readAsArrayBuffer(file);});}
async function joinSelectedAudio(){if(editingBusy())return;const plan=joinAudioPlan(project,[...selectedClips]);if(!plan){notify('Haz clic en dos bloques de la misma pista y pulsa W para unirlos.');return;}importing=true;setRecordUI();stopPlayback();previewPlan=null;setTaskProgress('Uniendo los dos bloques de audio…');try{await new Promise(resolve=>setTimeout(resolve,20));const buffer=await engine.render(plan.project,plan.start,plan.end);const track=project.tracks.find(t=>t.id===plan.trackId);if(!track||!plan.clipIds.every(cid=>track.clips.some(c=>c.id===cid)))throw Error('Los bloques han cambiado. Inténtalo de nuevo.');stash();const sourceId=id();sources.set(sourceId,buffer);const merged=makeClip(sourceId,plan.name,buffer.duration,plan.start);const index=track.clips.findIndex(c=>plan.clipIds.includes(c.id));track.clips=track.clips.filter(c=>!plan.clipIds.includes(c.id));track.clips.splice(index,0,merged);selectedTrack=track.id;selectedClip=merged.id;selectedVolumePoint=null;project.region=null;dirty();render();finishTaskProgress('Los dos audios se han unido en un bloque');notify('Audios unidos. Puedes deshacer la unión con Ctrl+Z.');}catch(error){finishTaskProgress('No se pudieron unir los audios',true);notify(error.message,true);}finally{importing=false;setRecordUI();}}
async function importAudio(files,targetId=null,at=position){if(recording||recordPending||importing||exporting)return;const list=[...files];if(!list.length)return;importing=true;setRecordUI();document.body.classList.add('busy');stopPlayback();stash();let imported=0;try{const ctx=await engine.init();for(const [index,file] of list.entries()){status(`Importando ${file.name}…`);try{const data=await readAudioFile(file,`Cargando ${index+1}/${list.length} · ${file.name}`);setTaskProgress(`Preparando el audio ${index+1}/${list.length} · ${file.name}`);await new Promise(resolve=>setTimeout(resolve,15));let buffer=await ctx.decodeAudioData(data);if(buffer.numberOfChannels>2){const mix=new OfflineAudioContext(2,buffer.length,buffer.sampleRate),source=mix.createBufferSource();source.buffer=buffer;source.connect(mix.destination);source.start();buffer=await mix.startRendering();}if(!buffer.duration)throw Error('Audio vacío');let track=targetId?project.tracks.find(t=>t.id===targetId):null;if(!track&&list.length===1)track=project.tracks.find(t=>t.id===selectedTrack);if(!track){track=makeTrack(file.name.replace(/\.[^.]+$/,''),project.tracks.length);project.tracks.push(track);}const sid=id();sources.set(sid,buffer);const c=makeClip(sid,file.name.replace(/\.[^.]+$/,''),buffer.duration,at);track.clips.push(c);selectedTrack=track.id;selectedClip=c.id;imported++;}catch(e){notify(`No se pudo importar «${file.name}». Revisa el formato o el archivo.`,true);}}if(imported){dirty();render();fitZoom();notify(`${imported} ${imported===1?'audio importado':'audios importados'}.`);}else{history.pop();render();}}catch(e){history.pop();notify(e.message,true);}finally{finishTaskProgress(imported?`${imported} ${imported===1?'audio cargado':'audios cargados'}`:'No se pudo cargar el audio',!imported);importing=false;setRecordUI();document.body.classList.remove('busy');}}
function fitZoom(){const available=$('#arrangeScroll').clientWidth-trackWidth()-35;zoom=clamp(available/Math.max(10,projectDuration(project)+3),5,200);$('#zoomRange').value=zoom;$('#arrangeScroll').scrollLeft=0;renderTimeline();updatePlayhead();}
function setZoom(value){zoom=clamp(value,5,200);$('#zoomRange').value=zoom;renderTimeline();updatePlayhead();}
async function chooseNew(){if(recording||recordPending||importing||exporting)return;const clips=project.tracks.some(t=>t.clips.length);if(clips&&!await confirmAction('¿Crear un nuevo proyecto?','Guarda una copia si quieres conservar la sesión actual.'))return;stopPlayback(true);stash();previewPlan=null;welcomeDismissed=true;project=makeProject();selectedTrack=project.tracks[0].id;selectedClip=null;loop=false;dirty();render();setZoom(36);notify('Nuevo proyecto preparado.');}
