async function loadDemo(ask=true){if(recording||recordPending||importing||exporting)return;if(ask&&project.tracks.some(t=>t.clips.length)&&!await confirmAction('¿Abrir el proyecto de demostración?','Guarda una copia para conservar tu sesión actual.'))return;try{stopPlayback(true);const ctx=await engine.init(false);if(ask)stash();project=makeProject();project.name='Demo · Mesa de producción';project.tracks.forEach(t=>{t.armed=false;});project.tracks[0].name='Sintonía';project.tracks[1].name='Base musical';project.tracks[2].name='Cierre';const durations=[12,24,6];for(let k=0;k<3;k++){const n=Math.floor(durations[k]*SAMPLE_RATE),buf=ctx.createBuffer(2,n,SAMPLE_RATE);for(let ch=0;ch<2;ch++){const arr=buf.getChannelData(ch);for(let i=0;i<n;i++){const t=i/SAMPLE_RATE;let v=0;if(k===0){const notes=[261.626,329.628,391.995,523.251,440,391.995,329.628,293.665],f=notes[Math.floor(t*2)%notes.length],e=Math.exp(-(t%.5)*9);v=.21*e*(Math.sin(2*Math.PI*f*t)+.18*Math.sin(2*Math.PI*f*2*t));}if(k===1){const beat=t%.5,kick=.35*Math.sin(2*Math.PI*(48+60*Math.exp(-beat*25))*beat)*Math.exp(-beat*22);const phase=t%2,pad=(Math.sin(2*Math.PI*130.813*t)+Math.sin(2*Math.PI*164.814*t)+Math.sin(2*Math.PI*(ch?196.15:195.85)*t))*.035;v=kick+pad*(.5+.5*Math.sin(Math.PI*phase/2));}if(k===2){const note=Math.floor(t*3)%4,f=[523.25,659.25,783.99,1046.5][note];v=.18*Math.sin(2*Math.PI*f*t)*Math.exp(-(t%(1/3))*12);}arr[i]=v;}}const sid=id();sources.set(sid,buf);const c=makeClip(sid,['Sintonía · demo','Ritmo y ambiente · demo','Firma sonora · demo'][k],durations[k],[0,3,21][k]);c.fadeIn=k===1?1:.05;c.fadeOut=k===1?2:1;project.tracks[k].clips.push(c);project.tracks[k].volume=[-3,-8,-4][k];}selectedTrack=project.tracks[0].id;selectedClip=project.tracks[0].clips[0].id;dirty();render();fitZoom();status('Demo · sonidos sintetizados. Pulsa Nuevo para crear tu sesión.');}catch(e){notify(e.message,true);}}
function microphoneError(e){return {NotAllowedError:'Permite el acceso al micrófono en el navegador para grabar.',NotFoundError:'No se ha encontrado un micrófono conectado.',NotReadableError:'El micrófono está ocupado. Cierra la otra aplicación y vuelve a intentarlo.',OverconstrainedError:'Ese micrófono no está disponible. Selecciona otra entrada.'}[e.name]||e.message;}
function setMicStatus(text,warning=false){const el=$('#micStatus');if(el.textContent!==text)el.textContent=text;el.classList.toggle('warning',warning);}
function drawRecordingWave(force=false){if(!recording)return;const canvas=$('#recordingWave');if(!canvas)return;const now=performance.now();if(!force&&Number(canvas.dataset.waveBins)>0&&recording.lastWaveDraw&&now-recording.lastWaveDraw<80)return;recording.lastWaveDraw=now;const duration=Math.max(.02,recording.waveDuration),width=Math.min(6000,Math.max(4,Math.ceil(duration*zoom))),height=canvas.clientHeight||60;canvas.width=width;canvas.height=height;const ctx=canvas.getContext('2d');if(!ctx)return;ctx.strokeStyle=trackVisual(project.tracks.find(t=>t.id===recording.track)).wave;ctx.lineWidth=1;ctx.beginPath();const count=Math.ceil(duration*50);for(let x=0;x<width;x++){const from=Math.floor(count*x/width),to=Math.max(from+1,Math.ceil(count*(x+1)/width));let low=0,high=0;for(let i=from;i<to;i++){const bin=recording.wave[i];if(bin){low=Math.min(low,bin.min);high=Math.max(high,bin.max);}}if(low!==high){ctx.moveTo(x,height/2+clamp(low,-1,1)*height*.44);ctx.lineTo(x,height/2+clamp(high,-1,1)*height*.44);}}ctx.stroke();canvas.dataset.waveBins=recording.wave.filter(Boolean).length;}
function captureRecordingWave(signal){if(!recording||recorder.stopping)return;const elapsed=Math.max(0,signal.elapsed),index=Math.floor(elapsed*50),old=recording.wave[index];recording.wave[index]={min:Math.min(old?.min??0,signal.min),max:Math.max(old?.max??0,signal.max)};recording.waveDuration=Math.max(recording.waveDuration,elapsed);position=recording.start+elapsed;updatePlayhead();drawRecordingWave();const expected=trackWidth()+timelineDuration()*zoom;if(parseFloat($('#timeline').style.width)<expected-zoom*4)$('#timeline').style.width=expected+'px';const sc=$('#arrangeScroll'),x=trackWidth()+position*zoom;if(x-sc.scrollLeft>sc.clientWidth-50)sc.scrollLeft=x-sc.clientWidth+100;}
function updateMicrophoneMeter(){if(!recorder?.stream){$('#micLevel i').style.width='0%';$('#micDb').textContent='—';return;}const signal=recorder.signal();captureRecordingWave(signal);$('#micLevel i').style.width=(signal.level*100)+'%';$('#micDb').textContent=Number.isFinite(signal.db)?Math.round(signal.db)+' dB':'−∞';let message=(recording?'Grabando · ':'Probando · ')+recorder.inputName,warning=false;if(signal.ended){message='Micrófono desconectado';warning=true;}else if(signal.muted){message='El micrófono está silenciado por el dispositivo o el sistema';warning=true;}else if(signal.suspended){message='El motor de entrada está suspendido · pulsa Probar micro de nuevo';warning=true;}else if(!recorder.signalSeen&&signal.elapsed>3){message='No llega señal · selecciona la entrada correcta y revisa el volumen del micrófono';warning=true;}else if(recorder.signalSeen)message+=' · señal recibida';setMicStatus(message,warning);}
function stopMicTest(){if(!micTesting)return;const heard=recorder?.signalSeen;recorder?.cleanup();micTesting=false;$('#testMic').textContent='Probar micro';$('#testMic').classList.remove('active');$('#testMic').setAttribute('aria-pressed','false');setMicStatus(heard?'Prueba finalizada · señal recibida':'Prueba finalizada · no se recibió señal',!heard);updateMicrophoneMeter();setRecordUI();}
async function testMicrophone(){if(recording||recordPending||importing||exporting)return;if(micTesting){stopMicTest();return;}recordPending=true;setRecordUI();setMicStatus('Esperando permiso del micrófono…');try{const ctx=await engine.init();recorder=new MicrophoneRecorder(ctx);recorder.onEnded=()=>{if(micTesting){stopMicTest();setMicStatus('El micrófono se ha desconectado',true);}};await recorder.test($('#micSelect').value);micTesting=true;$('#testMic').textContent='Finalizar prueba';$('#testMic').classList.add('active');$('#testMic').setAttribute('aria-pressed','true');await enumerateMics();updateMicrophoneMeter();}catch(e){recorder?.cleanup();setMicStatus(microphoneError(e),true);notify(microphoneError(e),true);}finally{recordPending=false;setRecordUI();}}
async function startRecording(){if(recording||recordPending){if(recording)await stopRecording();return;}if(exporting||importing)return;stopMicTest();recordPending=true;setRecordUI();$('#recordBtn').disabled=true;try{loop=false;previewPlan=null;stopPlayback();const ctx=await engine.init();recorder=new MicrophoneRecorder(ctx);recorder.onEnded=()=>{if(recording)stopRecording();};status('Esperando acceso al micrófono…');await recorder.start($('#micSelect').value);setMicStatus('Grabando · '+recorder.inputName);recorder.onEnded=()=>{if(recording){notify('El micrófono se ha desconectado. Finalizando la toma…',true);stopRecording();}};let track=project.tracks.find(t=>t.armed)||project.tracks.find(t=>t.id===selectedTrack);if(!track){stash();track=makeTrack('Grabación',project.tracks.length);project.tracks.push(track);}project.tracks.forEach(t=>t.armed=t.id===track.id);selectedTrack=track.id;selectedClip=null;recording={start:position,track:track.id,wave:[],waveDuration:0,lastWaveDraw:0};recordPending=false;$('#recordBtn').classList.add('recording');$('#recordBtn').setAttribute('aria-label','Finalizar grabación');render();await startPlayback();if(!engine.running)status('Grabando micrófono · la reproducción de acompañamiento no está disponible');enumerateMics();}catch(e){recorder?.cleanup();recording=null;recordPending=false;const message=microphoneError(e);setMicStatus(message,true);notify(message,true);$('#recordBtn').classList.remove('recording');render();}finally{recordPending=false;setRecordUI();}}
async function stopRecording(){if(!recording||recorder?.stopping)return;const take=recording;$('#recordBtn').disabled=true;stopPlayback();recordPending=true;setRecordUI();status('Finalizando la toma…');try{const buffer=await recorder.stop();recording=null;$('#recordBtn').classList.remove('recording');$('#recordBtn').setAttribute('aria-label','Grabar micrófono');if(buffer?.duration>.01){stash();const sid=id();sources.set(sid,buffer);const track=project.tracks.find(t=>t.id===take.track);const clip=makeClip(sid,`Toma · ${new Date().toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})}`,buffer.duration,take.start);track.clips.push(clip);selectedClip=clip.id;selectedTrack=track.id;position=take.start+clip.duration;dirty();let peak=0;for(let ch=0;ch<buffer.numberOfChannels;ch++)for(const value of buffer.getChannelData(ch))peak=Math.max(peak,Math.abs(value));if(peak<.00001){setMicStatus('La toma está en silencio · prueba otra entrada y revisa el nivel del micrófono',true);notify('La toma está en silencio. Pulsa Probar micro y selecciona una entrada con señal.',true);}else{setMicStatus('Toma guardada · '+recorder.inputName+' · señal recibida');notify(`Grabación añadida · ${formatTime(clip.duration,true)}.`);}}else{setMicStatus('La toma no contiene audio. Prueba el micrófono antes de grabar.',true);notify('La toma no contiene audio. Pulsa Probar micro y revisa la entrada.',true);}render();}catch(e){recording=null;recorder.cleanup();if(e.recordingBlob?.size){const ext=e.recordingBlob.type.includes('mp4')?'m4a':e.recordingBlob.type.includes('ogg')?'ogg':'webm';download(e.recordingBlob,'toma-recuperada.'+ext);}$('#recordBtn').classList.remove('recording');notify(e.message,true);render();}finally{recordPending=false;updateMicrophoneMeter();setRecordUI();}}
