function setRecordUI(){$('#testMic').disabled=!!recording||recordPending||importing||exporting;$('#outputSelect').disabled=!!exporting||!engine.canSelectOutput||!navigator.mediaDevices?.enumerateDevices;$('#recordBtn').disabled=recordPending||importing||exporting;for(const sel of ['#newBtn','#openBtn','#saveBtn','#importBtn','#addTrackBtn','#demoBtn','#exportBtn','#timeBtn','#micSelect','#emptyImport','#emptyDemo','#detectDevices'])$(sel).disabled=!!recording||recordPending||importing||exporting;}
function doSplit(time=position,cid=selectedClip,force=false){if(editingBusy())return;if(!force&&selectedSegment()){operateSegment('isolate');return;}const f=findClip(project,cid);if(!f)return;const elapsed=time-f.clip.start;if(elapsed<.005||elapsed>f.clip.duration-.005){notify('Sitúa el cursor dentro del clip para dividirlo.');return;}stash();const result=splitClip(project,cid,time);selectedClip=result.id;dirty();render();refreshAudio();}
