function handleTrackAction(e){const button=e.target.closest('[data-action]'),parent=e.target.closest('[data-track]');if(!button||!parent||editingBusy())return;const track=project.tracks.find(t=>t.id===parent.dataset.track);if(!track)return;const action=button.dataset.action;if(['volume','pan','name'].includes(action))return;stash();selectedTrack=track.id;if(action==='mute'||action==='solo'){if(action==='solo'){const enabled=!track.solo;for(const t of project.tracks)t.solo=t.id===track.id&&enabled;}else track.mute=!track.mute;for(const t of project.tracks)engine.updateTrack(t,project);}else if(action==='arm'){const armed=!track.armed;project.tracks.forEach(t=>t.armed=t.id===track.id&&armed);}else if(action==='remove-track'){if(track.clips.length){history.pop();confirmAction('¿Eliminar esta pista?',`Se quitará «${track.name}» y sus clips. Podrás deshacer la eliminación.`).then(ok=>{if(!ok)return;stash();project.tracks=project.tracks.filter(t=>t.id!==track.id);if(!findClip(project,selectedClip))selectedClip=null;selectedTrack=project.tracks[0]?.id;dirty();render();refreshAudio();});return;}project.tracks=project.tracks.filter(t=>t.id!==track.id);selectedTrack=project.tracks[0]?.id;}dirty();render();}
