function openVolumeDialog(context){if(editingBusy())return;const f=findClip(project,context.clipId);if(!f)return;volumeDialogContext={clipId:f.clip.id,time:context.volumeTime};const point=context.volumeTime===null?null:volumeNodes(f.clip).find(p=>Math.abs(p.time-context.volumeTime)<.003);$('#volumeDialogTarget').textContent=point?'Punto · '+formatTime(f.clip.start+point.time,true):'Bloque completo · '+f.clip.name;$('#volumeOperation').value='set';$('#volumeAmountUnit').value=volumeUnit;$('#volumeAmount').value=volumeValue(point?.gain??volumeNodes(f.clip)[0].gain);updateVolumeDialog();$('#volumeDialog').showModal();$('#volumeAmount').focus();$('#volumeAmount').select();}
function applyVolumeDialog(){if(editingBusy()||!volumeDialogContext)return;const context=volumeDialogContext,f=findClip(project,context.clipId);if(!f)return;const input=$('#volumeAmount');if(!input.value.trim()){$('#volumeAmountError').textContent='Escribe la cantidad que quieres aplicar.';return;}try{const staged=cloneProject(f.clip),unit=$('#volumeAmountUnit').value;adjustVolumeLevel(staged,Number(input.value),unit,$('#volumeOperation').value,context.time);stash();f.clip.volumePoints=staged.volumePoints;selectedClip=f.clip.id;selectedTrack=f.track.id;selectedVolumePoint=context.time===null?null:{clipId:f.clip.id,time:context.time};volumeUnit=unit;try{localStorage.setItem('viva-studio-volume-unit',volumeUnit);}catch{}dirty();engine.updateClip(f.clip);render();$('#volumeDialog').close();status('Volumen aplicado · '+volumeLabel(context.time===null?f.clip.volumePoints[0].gain:volumePointFor(f.clip).gain));}catch(error){$('#volumeAmountError').textContent=error.message;}}
function dragVolumePoint(e){const handle=e.target.closest('.volume-point,.volume-line-hit');if(!handle||e.button!==0||editingBusy())return;e.preventDefault();e.stopPropagation();const el=handle.closest('.clip'),found=findClip(project,el.dataset.clip);if(!found)return;select(found.clip.id,found.track.id,true);const c=found.clip,original=cloneProject(c),line=handle.classList.contains('volume-line-hit'),time=Number(handle.dataset.volumeTime),gain=Number(handle.dataset.volumeGain),startX=e.clientX,startY=e.clientY;let changed=false,point;const pointer=e.pointerId;handle.setPointerCapture(pointer);const height=el.querySelector('.volume-envelope').getBoundingClientRect().height||60;selectedVolumePoint=line?null:{clipId:c.id,time};renderInspector();const move=event=>{const dx=(event.clientX-startX)/zoom,delta=-(event.clientY-startY)/height*2;if(!changed&&Math.abs(event.clientX-startX)<2&&Math.abs(event.clientY-startY)<2)return;if(!changed){stash();changed=true;if(!line)point=addVolumePoint(project,c.id,c.start+time);}if(line){c.volumePoints=volumeNodes(original);shiftVolumeCurve(c,delta);}else{const nodes=c.volumePoints,index=nodes.indexOf(point);point.gain=Math.max(0,gain+delta);if(time>.003&&time<c.duration-.003)point.time=clamp(snapped(c.start+time+dx)-c.start,(nodes[index-1]?.time??0)+.003,(nodes[index+1]?.time??c.duration)-.003);}if(!line)selectedVolumePoint={clipId:c.id,time:point.time};updateVolumeGraphics(el,c);status(line?'Volumen del bloque · '+volumeLabel(c.volumePoints[0].gain):'Volumen del punto · '+volumeLabel(point.gain));};const finish=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel);try{handle.releasePointerCapture(pointer);}catch{}if(changed){dirty();render();}};const cancel=()=>{if(changed){Object.assign(c,original);history.pop();changed=false;updateVolumeGraphics(el,c);}finish();render();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);}

function dragTrackHeight(e){const handle=e.target.closest('.track-height-handle');if(!handle||e.button!==0||recordPending||importing||exporting)return;e.preventDefault();e.stopPropagation();const row=handle.closest('.track-row'),track=project.tracks.find(t=>t.id===row.dataset.track);if(!track)return;const original=trackHeight(track),startY=e.clientY,pointer=e.pointerId;let changed=false;handle.setPointerCapture(pointer);const paint=value=>{track.height=value;row.style.setProperty('--row-height',value+'px');row.classList.toggle('compact-track',value<90);row.querySelectorAll('.clip').forEach(drawWave);if(recording)drawRecordingWave(true);syncTrackHeight();};const move=event=>{const height=clamp(original+event.clientY-startY,60,260);if(Math.abs(height-original)<1&&!changed)return;if(!changed){stash();changed=true;}paint(height);status('Altura de '+track.name+' · '+Math.round(height)+' px');};const finish=()=>{handle.removeEventListener('pointermove',move);handle.removeEventListener('pointerup',finish);handle.removeEventListener('pointercancel',cancel);try{handle.releasePointerCapture(pointer);}catch{}if(changed)dirty();};const cancel=()=>{if(changed){paint(original);history.pop();changed=false;}finish();};handle.addEventListener('pointermove',move);handle.addEventListener('pointerup',finish);handle.addEventListener('pointercancel',cancel);}
function heightKeyboard(e){const handle=e.target.closest('.track-height-handle');if(!handle||!['ArrowUp','ArrowDown'].includes(e.key)||recordPending||importing||exporting)return;e.preventDefault();e.stopPropagation();const track=project.tracks.find(t=>t.id===handle.closest('.track-row').dataset.track);if(!track)return;stash();track.height=clamp(trackHeight(track)+(e.key==='ArrowUp'?-4:4),60,260);dirty();renderTimeline();$(`.track-row[data-track="${track.id}"] .track-height-handle`)?.focus();}
function bindTrackReorder(){const root=$('#trackRows');const clear=()=>{$$('.track-row').forEach(row=>row.classList.remove('drop-before','drop-after','dragging-track'));};root.addEventListener('dragstart',e=>{const handle=e.target.closest('.track-drag-handle');if(!handle)return;if(editingBusy()){e.preventDefault();return;}hideContextMenu();draggedTrack=handle.closest('.track-row').dataset.track;e.dataTransfer.setData('application/x-viva-track',draggedTrack);e.dataTransfer.effectAllowed='move';handle.closest('.track-row').classList.add('dragging-track');});root.addEventListener('dragover',e=>{if(!draggedTrack)return;const row=e.target.closest('.track-row');if(!row||row.dataset.track===draggedTrack)return;e.preventDefault();e.dataTransfer.dropEffect='move';clear();const rect=row.getBoundingClientRect(),after=e.clientY>=rect.top+rect.height/2;row.classList.add(after?'drop-after':'drop-before');});root.addEventListener('drop',e=>{if(!draggedTrack)return;e.preventDefault();e.stopPropagation();const row=e.target.closest('.track-row');if(row&&row.dataset.track!==draggedTrack){const rect=row.getBoundingClientRect(),after=e.clientY>=rect.top+rect.height/2;stash();if(moveTrack(project,draggedTrack,row.dataset.track,after)){dirty();render();status('Orden de las pistas actualizado');}else history.pop();}draggedTrack=null;clear();});root.addEventListener('dragend',()=>{draggedTrack=null;clear();});root.addEventListener('keydown',e=>{const handle=e.target.closest('.track-drag-handle');if(!handle||!e.altKey||!['ArrowUp','ArrowDown'].includes(e.key)||editingBusy())return;e.preventDefault();const source=handle.closest('.track-row').dataset.track,index=project.tracks.findIndex(t=>t.id===source),target=project.tracks[index+(e.key==='ArrowUp'?-1:1)];if(!target)return;stash();moveTrack(project,source,target.id,e.key==='ArrowDown');dirty();render();$(`.track-row[data-track="${source}"] .track-drag-handle`)?.focus();});}

function bind(){
$('#trackHeightRange').oninput=e=>{if(recordPending||importing||exporting)return;if(!e.target.dataset.history){stash();e.target.dataset.history='1';}for(const track of project.tracks)track.height=clamp(Number(e.target.value),60,260);dirty();renderTimeline();};$('#trackHeightRange').onchange=e=>delete e.target.dataset.history;$('#trackRows').addEventListener('pointerdown',dragTrackHeight);$('#trackRows').addEventListener('keydown',heightKeyboard);
$('#volumeOperation').onchange=$('#volumeAmountUnit').onchange=updateVolumeDialog;$('#applyVolume').onclick=applyVolumeDialog;
$('#testMic').onclick=testMicrophone;$('#micSelect').addEventListener('change',()=>{if(micTesting){stopMicTest();testMicrophone();}});audioDevices=new AudioDevices({input:$('#micSelect'),output:$('#outputSelect'),status:$('#deviceStatus'),engine,onMessage:notify});$('#detectDevices').onclick=async()=>{try{$('#detectDevices').disabled=true;await audioDevices.requestPermission();}catch(e){notify(e.name==='NotAllowedError'?'Permite el micrófono para mostrar los nombres de los dispositivos.':e.message,true);}finally{$('#detectDevices').disabled=false;}};$('#authorizeOutput').onclick=async()=>{try{await audioDevices.requestOutput();}catch(e){notify(e.name==='NotAllowedError'?'No se autorizó la salida de audio.':e.message,true);}};$('#authorizeOutput').hidden=!navigator.mediaDevices?.selectAudioOutput;

$('#importBtn').onclick=$('#emptyImport').onclick=()=>$('#audioInput').click();$('#audioInput').onchange=e=>{importAudio(e.target.files);e.target.value='';};$('#addTrackBtn').onclick=()=>{if(recording)return;stash();const t=makeTrack(`Pista ${project.tracks.length+1}`,project.tracks.length);project.tracks.push(t);selectedTrack=t.id;selectedClip=null;dirty();render();};
$('#newBtn').onclick=chooseNew;$('#emptyBlank').onclick=()=>{welcomeDismissed=true;render();status('Proyecto en blanco · importa un audio o empieza a grabar');};$('#recoverSession').onclick=async()=>{if(!recoverySession||editingBusy())return;try{await restoreRaw(recoverySession);notify('Sesión anterior recuperada.');}catch(e){notify(e.message,true);}};$('#trackRows').addEventListener('contextmenu',openAudioMenu);$('#contextMenu').addEventListener('click',handleAudioMenu);document.addEventListener('pointerdown',e=>{if(!e.target.closest('#contextMenu'))hideContextMenu();});bindTrackReorder();$('#demoBtn').onclick=$('#emptyDemo').onclick=()=>loadDemo();$('#saveBtn').onclick=$('#confirmSave').onclick=saveProject;$('#openBtn').onclick=()=>$('#projectInput').click();$('#projectInput').onchange=async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(project.tracks.some(t=>t.clips.length)&&!await confirmAction('¿Abrir otro proyecto?','Guarda una copia si quieres conservar la sesión actual.'))return;try{status('Abriendo proyecto…');const raw=await unpackProject(file);await restoreRaw(raw);dirty();notify('Proyecto abierto con todos sus audios.');}catch(err){notify(err.message,true);}};
$('#projectName').onchange=e=>{if(recording)return;stash();project.name=e.target.value.trim()||'Mi sesión';e.target.value=project.name;dirty();};$('#undoBtn').onclick=()=>undo();$('#redoBtn').onclick=()=>undo(true);$('#playBtn').onclick=togglePlay;$('#stopBtn').onclick=async()=>{if(recording)await stopRecording();else stopPlayback();status('Detenido');};$('#rewindBtn').onclick=()=>seek(0);$('#recordBtn').onclick=startRecording;$('#loopBtn').onclick=()=>{if(recording)return;loop=!loop;if(loop&&project.region)seek(project.region.start);updateCounts();};$('#timeBtn').onclick=()=>{const value=prompt('Posición en segundos:',position.toFixed(3));if(value!==null&&Number.isFinite(Number(value)))seek(Number(value));};$('#zoomRange').oninput=e=>setZoom(Number(e.target.value));$('#zoomOut').onclick=()=>setZoom(zoom/1.3);$('#zoomIn').onclick=()=>setZoom(zoom*1.3);$('#fitBtn').onclick=fitZoom;
$('#moveTool').onclick=()=>{tool='move';$('#moveTool').classList.add('active');$('#cutTool').classList.remove('active');};$('#cutTool').onclick=()=>{tool='cut';$('#cutTool').classList.add('active');$('#moveTool').classList.remove('active');};$('#splitBtn').onclick=()=>doSplit();$('#duplicateBtn').onclick=()=>{if(selectedSegment()){operateSegment('duplicate');return;}stash();const c=duplicateClip(project,selectedClip);if(c){selectedClip=c.id;dirty();render();refreshAudio();}};$('#deleteBtn').onclick=deleteSelected;
$('#trackRows').addEventListener('click',e=>{handleTrackAction(e);const row=e.target.closest('.track-row');if(!row)return;if(e.target.closest('.clip,.track-height-handle')||e.target.closest('button'))return;if(!e.target.closest('input')){select(null,row.dataset.track);if(e.target.closest('.lane')&&!dragging)seek(snapped(Math.max(0,(e.clientX-e.target.closest('.lane').getBoundingClientRect().left)/zoom)));}});$('#trackRows').addEventListener('pointerdown',dragVolumePoint);$('#trackRows').addEventListener('pointerdown',dragClip);$('#ruler').addEventListener('pointerdown',dragRuler);
for(const sel of ['#trackRows','#mixerChannels']){$(sel).addEventListener('input',trackSlider);$(sel).addEventListener('change',e=>{delete e.target.dataset.history;if(e.target.dataset.action==='name'){const t=project.tracks.find(t=>t.id===e.target.closest('[data-track]')?.dataset.track);if(t){stash();t.name=e.target.value.trim()||'Pista';dirty();render();}}});}$('#mixerChannels').addEventListener('click',handleTrackAction);$('#mixerChannels').addEventListener('input',e=>{if(e.target.id==='masterVolume'){if(!e.target.dataset.history){stash();e.target.dataset.history='1';}project.master=Number(e.target.value);$('#masterDB').textContent=(project.master<=-60?'−∞':project.master.toFixed(1))+' dB';engine.updateMaster(project.master);dirty();}});$('#inspectorContent').addEventListener('input',inspectorInput);$('#inspectorContent').addEventListener('change',inspectorChange);$('#inspectorContent').addEventListener('click',e=>{if(recording)return;if(e.target.id==='inspectorIsolate')operateSegment('isolate');if(e.target.id==='normalizeClip')normalizeClip();if(e.target.id==='renameSource'){const f=findClip(project,selectedClip);if(f){stash();const offset=f.clip.offset;f.clip.start=Math.max(0,f.clip.start-offset);f.clip.points=(f.clip.points||[]).map(p=>p+offset);f.clip.volumePoints=(f.clip.volumePoints||[]).map(p=>({...p,time:p.time+offset}));f.clip.offset=0;f.clip.duration=sources.get(f.clip.source).duration;dirty();render();refreshAudio();}}if(e.target.id==='resetFX'){const t=project.tracks.find(t=>t.id===selectedTrack);if(t){stash();t.eq={low:0,mid:0,high:0};t.compressor=false;dirty();render();refreshAudio();}}});$('#mixerToggle').onclick=()=>{const collapsed=$('.mixer').classList.toggle('collapsed');$('#mixerToggle').innerHTML=(collapsed?'Expandir':'Contraer')+' '+icon('chevron');};$('#helpBtn').onclick=()=>$('#helpDialog').showModal();$('#exportBtn').onclick=openExport;$('#doExport').onclick=performExport;$('#exportScope').onchange=updateExportDuration;$('#exportFormat').onchange=()=>$('#exportBitrate').disabled=$('#exportFormat').value==='wav';$('#exportDialog').addEventListener('close',cancelExport);$('#exportDialog').addEventListener('cancel',cancelExport);
const editor=$('.arrangement');editor.addEventListener('dragover',e=>{if(e.dataTransfer.types.includes('Files')){e.preventDefault();editor.classList.add('drag-over');}});editor.addEventListener('dragleave',e=>{if(!editor.contains(e.relatedTarget))editor.classList.remove('drag-over');});editor.addEventListener('drop',e=>{if(!e.dataTransfer.files?.length)return;e.preventDefault();editor.classList.remove('drag-over');const lane=e.target.closest('.lane');importAudio(e.dataTransfer.files,lane?.dataset.track??null,lane?snapped(Math.max(0,(e.clientX-lane.getBoundingClientRect().left)/zoom)):position);});
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!$('#contextMenu').hidden){hideContextMenu();return;}if(e.target.matches('input,textarea,select')||$('dialog[open]'))return;const mod=e.ctrlKey||e.metaKey;if(mod&&e.key.toLowerCase()==='s'){e.preventDefault();saveProject();return;}if(mod&&e.key.toLowerCase()==='z'){e.preventDefault();undo(e.shiftKey);return;}if(mod&&e.key.toLowerCase()==='y'){e.preventDefault();undo(true);return;}if(mod&&e.key.toLowerCase()==='c'&&selectedClip){e.preventDefault();copySegment();return;}if(mod&&e.key.toLowerCase()==='x'&&selectedClip){e.preventDefault();copySegment(true);return;}if(mod&&e.key.toLowerCase()==='v'&&clipboard&&selectedTrack){e.preventDefault();pasteSegment(selectedTrack,position);return;}if(mod&&e.key.toLowerCase()==='d'&&selectedClip){e.preventDefault();$('#duplicateBtn').click();return;}if(e.code==='Space'){e.preventDefault();togglePlay();}else if(e.key.toLowerCase()==='r'){e.preventDefault();startRecording();}else if(e.key.toLowerCase()==='s'&&!mod)doSplit();else if(e.key.toLowerCase()==='w'&&!mod){e.preventDefault();joinSelectedAudio();}else if(e.key==='Delete'||e.key==='Backspace'){e.preventDefault();deleteSelected();}else if(e.key==='Home'){e.preventDefault();seek(0);}else if(e.key==='Escape'){project.region=null;loop=false;updateRegion();renderInspector();updateCounts();}});
window.addEventListener('pagehide',()=>recorder?.cleanup());window.addEventListener('resize',()=>{renderTimeline();updatePlayhead();});window.addEventListener('beforeunload',e=>{if(recording||revision!==savedRevision){e.preventDefault();e.returnValue='';}});document.addEventListener('visibilitychange',()=>{if(document.hidden&&revision!==savedRevision)autoSave();});document.addEventListener('visibilitychange',()=>{if(!document.hidden)enumerateMics();});
}
async function boot(){bind();render();animate();enumerateMics();$('#saveState').textContent='Proyecto en blanco';try{db=await initDatabase();recoverySession=await new Promise((resolve,reject)=>{const req=db.transaction('projects').objectStore('projects').get('current');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error);});$('#recoverSession').hidden=!recoverySession;}catch(e){$('#saveState').textContent='Proyecto en blanco · sin autoguardado';}setRecordUI();}
